class Evaluator:
    def __init__(self, expression: str):
        self.expression = expression.replace(" ", "")
        self.position = 0

    def parse(self) -> float:
        return self.add_subtract()

    def add_subtract(self) -> float:
        result = self.multiply_divide()
        while self.position < len(self.expression):
            if self.expression[self.position] == '+':
                self.position += 1
                result += self.multiply_divide()
            elif self.expression[self.position] == '-':
                self.position += 1
                result -= self.multiply_divide()
            else:
                break
        return result

    def multiply_divide(self) -> float:
        result = self.number()
        while self.position < len(self.expression):
            if self.expression[self.position] == '*':
                self.position += 1
                result *= self.number()
            elif self.expression[self.position] == '/':
                self.position += 1
                result /= self.number()
            else:
                break
        return result

    def number(self) -> float:
        if self.position >= len(self.expression):
            raise ValueError("Invalid expression")

        if self.expression[self.position] == '(':
            self.position += 1
            result = self.add_subtract()
            if self.position < len(self.expression) and self.expression[self.position] == ')':
                self.position += 1
                return result
            else:
                raise ValueError("Mismatched parentheses")

        start = self.position
        while (self.position < len(self.expression) and
               (self.expression[self.position].isdigit() or self.expression[self.position] == '.')):
            self.position += 1

        number_str = self.expression[start:self.position]

        if number_str:
            return float(number_str)
        raise ValueError("Invalid number")

