def evaluate(expr: str) -> float:
    """
    Evaluates an arithmetic expression using the Shunting Yard algorithm to 
    convert infix expressions to postfix notation, followed by evaluation of 
    the postfix expression.
    """
    def precedence(op: str) -> int:
        if op in ('+', '-'):
            return 1
        if op in ('*', '/'):
            return 2
        return 0

    def apply_operator(operators: list, values: list) -> None:
        operator = operators.pop()
        right = values.pop()
        left = values.pop()
        if operator == '+':
            values.append(left + right)
        elif operator == '-':
            values.append(left - right)
        elif operator == '*':
            values.append(left * right)
        elif operator == '/':
            values.append(left / right)

    def infix_to_postfix(expression: str) -> list:
        output = []
        operators = []
        i = 0
        while i < len(expression):
            char = expression[i]
            if char.isdigit() or char == '.':
                num_str = ''
                while i < len(expression) and (expression[i].isdigit() or expression[i] == '.'):
                    num_str += expression[i]
                    i += 1
                output.append(float(num_str))
                continue
            elif char in "+-*/":
                while (operators and precedence(operators[-1]) >= precedence(char)):
                    apply_operator(operators, output)
                operators.append(char)
            elif char == '(':
                operators.append(char)
            elif char == ')':
                while operators and operators[-1] != '(':
                    apply_operator(operators, output)
                operators.pop()  # Pop the '('
            i += 1

        while operators:
            apply_operator(operators, output)

        return output

    postfix = infix_to_postfix(expr.replace(" ", ""))
    values = []
    for token in postfix:
        values.append(token)

    return values[0] if values else 0.0

