def evaluate(expr: str) -> float:
    """
    Evaluates an arithmetic expression using the recursive descent parsing approach
    with a focus on an explicit state machine to manage operator precedence and 
    support for parentheses.
    """
    class Parser:
        def __init__(self, expression: str):
            self.tokens = self.tokenize(expression.replace(" ", ""))
            self.pos = 0

        def tokenize(self, expr: str) -> list:
            tokens = []
            number_buffer = []
            for char in expr:
                if char.isdigit() or char == '.':
                    number_buffer.append(char)
                else:
                    if number_buffer:
                        tokens.append(''.join(number_buffer))
                        number_buffer.clear()
                    if char in '+-*/()':
                        tokens.append(char)
            if number_buffer:
                tokens.append(''.join(number_buffer))
            return tokens

        def parse(self) -> float:
            return self.expr()

        def expr(self) -> float:
            result = self.term()
            while self.pos < len(self.tokens):
                token = self.tokens[self.pos]
                if token == '+':
                    self.pos += 1
                    result += self.term()
                elif token == '-':
                    self.pos += 1
                    result -= self.term()
                else:
                    break
            return result

        def term(self) -> float:
            result = self.factor()
            while self.pos < len(self.tokens):
                token = self.tokens[self.pos]
                if token == '*':
                    self.pos += 1
                    result *= self.factor()
                elif token == '/':
                    self.pos += 1
                    result /= self.factor()
                else:
                    break
            return result

        def factor(self) -> float:
            token = self.tokens[self.pos]
            if token == '(':
                self.pos += 1
                result = self.expr()
                if self.tokens[self.pos] != ')':
                    raise ValueError("Mismatched parentheses")
                self.pos += 1
                return result
            else:
                self.pos += 1
                return float(token)

    parser = Parser(expr)
    return parser.parse()

def evaluate(expr: str) -> float:
    """
    Evaluates an arithmetic expression using a stack-based approach to handle operator precedence
    and parentheses without recursion.
    """
    def operate(a: float, b: float, op: str) -> float:
        if op == '+':
            return a + b
        elif op == '-':
            return a - b
        elif op == '*':
            return a * b
        elif op == '/':
            return a / b
        raise ValueError("Invalid operator")

    def precedence(op: str) -> int:
        if op in ('+', '-'):
            return 1
        if op in ('*', '/'):
            return 2
        return 0

    def compute(values: list, ops: list) -> None:
        right = values.pop()
        left = values.pop()
        op = ops.pop()
        values.append(operate(left, right, op))

    expr = expr.replace(' ', '')
    values = []
    ops = []
    i, n = 0, len(expr)

    while i < n:
        if expr[i].isdigit() or expr[i] == '.':
            j = i
            while j < n and (expr[j].isdigit() or expr[j] == '.'):
                j += 1
            values.append(float(expr[i:j]))
            i = j
        elif expr[i] in '+-*/':
            while (ops and precedence(ops[-1]) >= precedence(expr[i])):
                compute(values, ops)
            ops.append(expr[i])
            i += 1
        elif expr[i] == '(':
            ops.append(expr[i])
            i += 1
        elif expr[i] == ')':
            while ops and ops[-1] != '(':
                compute(values, ops)
            ops.pop()  # pop '('
            i += 1
        else:
            raise ValueError("Invalid character in expression")

    while ops:
        compute(values, ops)

    return values[0] if values else 0.0
